import org.junit.jupiter.api.Test;

/**
 * Packed plan-cache hits must be authenticated by the collision-proof packed identity, never by a (possibly lossy)
 * {@code TupleExpr.equals}. Queries that differ only in an operator parameter share a routing fingerprint and must
 * still never share a plan.
 */
class PackedPlanCacheOperatorParameterIdentityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");

	@Test
	void starPathPlanIsNotServedForPlusPath() {
		PackedPlanCache cache = new PackedPlanCache(32, 4);
		PackedPlanCache.Context context = context(11L);

		PackedPlanningResult star = PackedCascadesPlanner.optimize(path(0L), OptimizationGoal.root(), cache,
				context);
		PackedPlanningResult plus = PackedCascadesPlanner.optimize(path(1L), OptimizationGoal.root(), cache,
				context);

		assertFalse(star.metrics().planCacheHit());
		assertFalse(plus.metrics().planCacheHit(), "p+ must not be served the cached p* plan");
		assertEquals(0L, arbitraryLengthPath(star.selectedPlan()).getMinLength());
		assertEquals(1L, arbitraryLengthPath(plus.selectedPlan()).getMinLength());

		PackedPlanningResult starAgain = PackedCascadesPlanner.optimize(path(0L), OptimizationGoal.root(), cache,
				context);
		assertTrue(starAgain.metrics().planCacheHit(), "the genuine p* re-run must still hit");
		assertEquals(0L, arbitraryLengthPath(starAgain.selectedPlan()).getMinLength());
	}

	@Test
	void plusPathPlanIsNotServedForStarPath() {
		PackedPlanCache cache = new PackedPlanCache(32, 4);
		PackedPlanCache.Context context = context(11L);

		PackedCascadesPlanner.optimize(path(1L), OptimizationGoal.root(), cache, context);
		PackedPlanningResult star = PackedCascadesPlanner.optimize(path(0L), OptimizationGoal.root(), cache,
				context);

		assertFalse(star.metrics().planCacheHit(), "p* must not be served the cached p+ plan");
		assertEquals(0L, arbitraryLengthPath(star.selectedPlan()).getMinLength());
	}

	@Test
	void groupConcatPlanIsNotServedForOtherSeparator() {
		PackedPlanCache cache = new PackedPlanCache(32, 4);
		PackedPlanCache.Context context = context(11L);

		PackedPlanningResult comma = PackedCascadesPlanner.optimize(groupConcat(","), OptimizationGoal.root(), cache,
				context);
		PackedPlanningResult pipe = PackedCascadesPlanner.optimize(groupConcat("|"), OptimizationGoal.root(), cache,
				context);

		assertFalse(comma.metrics().planCacheHit());
		// The separator is a constant, so the parameterized family may reuse the plan template and re-materialize
		// it with the requested separator; what must never happen is the exact-entry hit that replays the ',' query.
		assertFalse(pipe.metrics().planCacheHit() && pipe.metrics().queryTemplateCacheHit(),
				"separator '|' must not be served the cached ',' plan through an exact-entry hit");
		assertEquals(",", separator(comma.selectedPlan()));
		assertEquals("|", separator(pipe.selectedPlan()), "the materialized plan must carry the requested separator");

		PackedPlanningResult commaAgain = PackedCascadesPlanner.optimize(groupConcat(","), OptimizationGoal.root(),
				cache, context);
		assertTrue(commaAgain.metrics().planCacheHit(), "the genuine ',' re-run must still hit");
		assertEquals(",", separator(commaAgain.selectedPlan()));
	}

	@Test
	void familyReuseAcrossConstantsMaterializesTheRequestedConstant() {
		PackedPlanCache cache = new PackedPlanCache(32, 4);
		PackedPlanCache.Context context = context(11L);

		PackedCascadesPlanner.optimize(constantObjectPattern(A), OptimizationGoal.root(), cache, context);
		PackedPlanningResult other = PackedCascadesPlanner.optimize(constantObjectPattern(B),
				OptimizationGoal.root(), cache, context);

		assertFalse(other.metrics().planCacheHit() && other.metrics().queryTemplateCacheHit(),
				"a different constant must never be an exact-entry hit");
		assertEquals(B, objectConstant(other.selectedPlan()),
				"family reuse must re-materialize the plan with the requested constant");
	}

	@Test
	void identityMismatchRejectsEqualLookingSource() {
		// Force the routing collision so the test pins the authentication order, not the fingerprint.
		PackedPlanCache cache = new PackedPlanCache(32, 4, ignored -> new PackedPlanCache.Fingerprint(7L, 9L));
		PackedPlanCache.Context context = context(11L);
		TupleExpr first = lossyScopePattern(StatementPattern.Scope.DEFAULT_CONTEXTS);
		TupleExpr second = lossyScopePattern(StatementPattern.Scope.NAMED_CONTEXTS);
		assertEquals(first, second, "fixture: the two sources must compare equal under the lossy equals");
		assertEquals(first.hashCode(), second.hashCode());

		PackedCascadesPlanner.optimize(first, OptimizationGoal.root(), cache, context);
		PackedPlanningResult collision = PackedCascadesPlanner.optimize(second, OptimizationGoal.root(), cache,
				context);

		assertFalse(collision.metrics().planCacheHit(),
				"a packed identity mismatch must reject the hit even when TupleExpr.equals says the trees are equal");
		assertFalse(collision.metrics().queryTemplateCacheHit());
		assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, scope(collision.selectedPlan()));
	}

	@Test
	void identityMatchStillReusesTheGenuinePlan() {
		PackedPlanCache cache = new PackedPlanCache(32, 4, ignored -> new PackedPlanCache.Fingerprint(7L, 9L));
		PackedPlanCache.Context context = context(11L);

		PackedCascadesPlanner.optimize(lossyScopePattern(StatementPattern.Scope.NAMED_CONTEXTS),
				OptimizationGoal.root(), cache, context);
		PackedPlanningResult hot = PackedCascadesPlanner.optimize(
				lossyScopePattern(StatementPattern.Scope.NAMED_CONTEXTS), OptimizationGoal.root(), cache, context);

		assertTrue(hot.metrics().planCacheHit());
		assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, scope(hot.selectedPlan()));
	}

	private static TupleExpr path(long minLength) {
		StatementPattern step = new StatementPattern(Var.of("s"), Var.of("_const_p", P, true, true), Var.of("o"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(Var.of("s"), step, Var.of("o"), minLength);
		return new Projection(path, new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("o")));
	}

	private static TupleExpr groupConcat(String separator) {
		GroupConcat concat = new GroupConcat(Var.of("o"));
		concat.setSeparator(new ValueConstant(VF.createLiteral(separator)));
		Group group = new Group(new StatementPattern(Var.of("s"), Var.of("_const_p", P, true, true), Var.of("o")),
				List.of(), List.of(new GroupElem("c", concat)));
		return new Projection(group, new ProjectionElemList(new ProjectionElem("c")));
	}

	private static TupleExpr constantObjectPattern(IRI object) {
		return new Projection(new StatementPattern(Var.of("s"), Var.of("_const_p", P, true, true),
				Var.of("_const_o", object, true, true)), new ProjectionElemList(new ProjectionElem("s")));
	}

	private static TupleExpr lossyScopePattern(StatementPattern.Scope scope) {
		return new Projection(new LossyScopeStatementPattern(scope, Var.of("s"), Var.of("_const_p", P, true, true),
				Var.of("o")), new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("o")));
	}

	private static StatementPattern.Scope scope(TupleExpr plan) {
		List<StatementPattern> patterns = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				patterns.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, patterns.size());
		return patterns.get(0).getScope();
	}

	private static ArbitraryLengthPath arbitraryLengthPath(TupleExpr plan) {
		List<ArbitraryLengthPath> paths = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ArbitraryLengthPath node) {
				paths.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, paths.size(), "plan must contain exactly one property path");
		return paths.get(0);
	}

	private static String separator(TupleExpr plan) {
		List<GroupConcat> concats = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(GroupConcat node) {
				concats.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, concats.size(), "plan must contain exactly one GROUP_CONCAT");
		ValueConstant separator = (ValueConstant) concats.get(0).getSeparator();
		assertNotNull(separator);
		return ((Literal) separator.getValue()).getLabel();
	}

	private static IRI objectConstant(TupleExpr plan) {
		List<StatementPattern> patterns = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				patterns.add(node);
				super.meet(node);
			}
		});
		assertEquals(1, patterns.size());
		return (IRI) patterns.get(0).getObjectVar().getValue();
	}

	private static PackedPlanCache.Context context(long dataRevision) {
		return new PackedPlanCache.Context(1L, 0L, 0L, 4L, 5L, 6L, dataRevision);
	}

	/**
	 * A statement pattern whose {@code equals}/{@code hashCode} deliberately ignore the context scope (a semantic
	 * operator parameter the packed codec encodes but the routing fingerprint does not hash): it stands in for any
	 * lossy model equality so the test pins the authentication order, not one particular operator.
	 */
	private static final class LossyScopeStatementPattern extends StatementPattern {

		private LossyScopeStatementPattern(Scope scope, Var subject, Var predicate, Var object) {
			super(scope, subject, predicate, object);
		}

		@Override
		public boolean equals(Object other) {
			return other instanceof LossyScopeStatementPattern o && getSubjectVar().equals(o.getSubjectVar())
					&& getPredicateVar().equals(o.getPredicateVar()) && getObjectVar().equals(o.getObjectVar());
		}

		@Override
		public int hashCode() {
			return (getSubjectVar().hashCode() * 31 + getPredicateVar().hashCode()) * 31 + getObjectVar().hashCode();
		}
	}
}
